 Object.entries(organizations).forEach(([key,o])=>{o.closures=[];o.activity=[];o.availability=o.hours;o.locations=[{id:'LOC-1',name:'Main site',address:o.address,hours:o.hours}];o.resources=key==='hospital'?[{name:'Dr. Priya Sharma',kind:'Clinician',days:'Monday–Saturday',start:'08:00',end:'20:00',capacity:1},{name:'Consultation Room 1',kind:'Room',days:'Monday–Saturday',start:'08:00',end:'20:00',capacity:1}]:key==='diagnostics'?[{name:'Sample collection',kind:'Service',days:'Monday–Saturday',start:'07:00',end:'19:00',capacity:2},{name:'Imaging room',kind:'Room / equipment',days:'Monday–Saturday',start:'07:00',end:'19:00',capacity:1}]:[];o.resources.forEach(r=>r.location='Main site');o.stock?.forEach(s=>s.location='Main site');o.sales?.forEach(s=>s.productName=o.catalogue.find(p=>p.id===s.product).name);o.purchases?.forEach(p=>p.productName=o.catalogue.find(c=>c.id===p.product).name);});
 organizations.pharmacy.locations.push({id:'LOC-2',name:'Dispensing counter',address:organizations.pharmacy.address,hours:organizations.pharmacy.hours});
