 let orgKey='hospital', page='dashboard', query='', filter='All', auditFilter='All', opsFilter='All', staffSort='Name A–Z', staffPageNum=1, selectedStaff=new Set(), timer, returnFocus;
 const org=()=>organizations[orgKey], esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=n=>'₹'+Number(n).toLocaleString('en-IN'), date=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});
 const badge=s=>`<span class="status ${['Active','Completed','Released','Received'].includes(s)?'good':['Inactive','Expired','Returned'].includes(s)?'bad':'warn'}">${esc(s)}</span>`;
