 const select=(id,label,options,value='')=>`<div class="form-group"><label class="form-label" for="${id}">${esc(label)}</label><select class="form-control" id="${id}" name="${id}">${options.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select><span class="field-error" id="${id}-error"></span></div>`;
