 function scheduleV2(){return header('Schedule & closures','Review resource hours, capacity and the effect of a closure.',button('Check availability','availability-check')+button('Add resource','resource-add')+(orgKey==='hospital'?button('Add hours exception','hours-exception-add'):'')+button('Add closure','closure-add','',true))+`<section class="card"><h2>Regular availability</h2>${org().resources.map((r,i)=>row(r.name,resourceSummary(r),button('Edit resource schedule','resource-edit',String(i)))).join('')}<p>Closures block new availability only. Existing bookings need explicit follow-up.</p></section><section class="card"><h2>${orgKey==='hospital'?'Closures and exceptions':'Closures'}</h2>${org().closures.map(c=>row(date(c.date)+' · '+c.resource,(orgKey==='hospital'?(c.kind==='Hours exception'?'Hours exception · '+sessionSummary(c.sessions)+' · ':'Closure · '):'')+c.reason+' · '+c.affected.length+' affected booking(s)',button('Review impact','closure-detail',c.id),c.ack?'Follow-up assigned':'Needs follow-up')).join('')||empty(orgKey==='hospital'?'No closures or exceptions have been added.':'No closures have been added.')}</section>`;}
 function sessionRow(s,i){return `<div class="session-row" data-session-row><div class="session-times">${input('session-start-'+i,'Session '+(i+1)+' starts',s.start,'time')}${input('session-end-'+i,'Session '+(i+1)+' ends',s.end,'time')}</div><button type="button" class="btn btn-ghost" data-remove-session aria-label="Remove session ${i+1}">Remove session</button></div>`;}
 function sessionsForm(title,initial,fields,save,label,note){let serial=0;form(title,fields+`<fieldset class="sessions-fieldset"><legend>Daily time sessions</legend><p class="read-note">Add each continuous period separately. Breaks remain unavailable.</p><div id="session-rows">${initial.map(s=>sessionRow(s,serial++)).join('')}</div><button type="button" class="btn btn-ghost" id="add-session">Add time session</button></fieldset>`,save,label,note);dialog.querySelector('#add-session').onclick=()=>{dialog.querySelector('#session-rows').insertAdjacentHTML('beforeend',sessionRow({start:'',end:''},serial++));errors([]);};dialog.querySelector('#session-rows').onclick=e=>{if(e.target.closest('[data-remove-session]')){const rows=dialog.querySelectorAll('[data-session-row]');if(rows.length>1){e.target.closest('[data-session-row]').remove();dialog.querySelectorAll('[data-session-row]').forEach((row,i)=>{row.querySelectorAll('input').forEach((field,j)=>{const id='session-'+(j?'end':'start')+'-'+i;field.id=id;field.name=id;row.querySelectorAll('label')[j].htmlFor=id;row.querySelectorAll('label')[j].textContent='Session '+(i+1)+(j?' ends':' starts');});row.querySelector('[data-remove-session]').setAttribute('aria-label','Remove session '+(i+1));});serial=rows.length-1;errors([]);}else toast('Keep at least one time session.');}};}
