 function hospitalResourceEdit(index){const r=org().resources[Number(index)];const days=`<fieldset class="weekdays-fieldset" id="weekday" tabindex="-1"><legend>Recurring weekdays</legend><div class="weekday-options">${weekdayNames.map((name,n)=>`<label><input type="checkbox" name="weekday" value="${n}" ${r.weekdays.includes(n)?'checked':''}> ${name}</label>`).join('')}</div><span class="field-error" id="weekday-error"></span></fieldset>`;sessionsForm('Edit resource schedule',r.sessions,days+input('capacity','Concurrent capacity',r.capacity,'number','min="1" max="50" step="1"'),d=>{const weekdays=[...dialog.querySelectorAll('[name="weekday"]:checked')].map(x=>+x.value),sessions=readSessions(),err=sessionErrors(sessions);if(!weekdays.length)err.push(['weekday','Select at least one recurring weekday.']);if(!Number.isInteger(+d.capacity)||+d.capacity<1||+d.capacity>50)err.push(['capacity','Enter a capacity from 1 to 50.']);if(errors(err))return;const before=resourceSummary(r);commit('Mock resource schedule updated. Existing bookings preserved.',()=>{Object.assign(r,{weekdays,sessions:sessions.map(({start,end})=>({start,end})),capacity:+d.capacity});logChange(r.name+' schedule changed',before,resourceSummary(r));});},'Save schedule','<p>Changes affect future mock availability. Existing bookings are not moved or notified.</p>');}
