 function purchasesV2(){return header('Purchases','Mock purchase orders and goods received.',button('Create purchase order','purchase-add','',true))+`<section class="card">${org().purchases.map(p=>row(p.id+' · '+(p.productName||item(p.product).name),p.supplier+' · '+(p.receivedQty||0)+'/'+p.qty+' packs received · '+money(p.qty*p.cost)+(p.discrepancy?' · Discrepancy: '+p.discrepancy:''),button('View purchase','purchase-detail',p.id)+((p.receivedQty||0)<p.qty&&!p.discrepancy?button('Receive stock','purchase-receive',p.id)+button('Record discrepancy','purchase-discrepancy',p.id):''),p.status)).join('')}</section>`;}
 function purchaseDiscrepancy(id){const p=org().purchases.find(x=>x.id===id),outstanding=p.qty-(p.receivedQty||0);form('Record purchase discrepancy',input('reason','Discrepancy reason'),d=>{if(errors(d.reason.trim()?[]:[['reason','Enter a discrepancy reason.']]))return;close();modal('Review discrepancy',details([['Order',p.id],['Outstanding packs',outstanding],['Reason',d.reason]])+'<p>This records an internal mock exception. No supplier message is sent.</p>',[{label:'Cancel'},{label:'Confirm discrepancy',primary:true,run:()=>{p.discrepancy=d.reason;p.status='Discrepancy recorded';logChange(p.id+' purchase discrepancy',outstanding+' outstanding',d.reason);render();toast('Mock discrepancy recorded.');}}]);},'Review discrepancy');}
 function purchaseReceiveV2(id){const p=org().purchases.find(x=>x.id===id),remaining=p.qty-(p.receivedQty||0);form('Receive stock',input('qty','Quantity received',remaining,'number',`min="1" max="${remaining}" step="1"`)+input('batch','Batch number')+input('expiry','Expiry date','','date',`min="${today}"`),d=>{const err=[];if(!Number.isInteger(+d.qty)||+d.qty<1||+d.qty>remaining)err.push(['qty','Enter 1 to '+remaining+' packs.']);if(!d.batch.trim())err.push(['batch','Enter a batch number.']);if(org().stock.some(s=>s.batch===d.batch))err.push(['batch','Batch already exists. Use a new sample batch.']);if(!d.expiry||d.expiry<=today)err.push(['expiry','Choose an expiry date after today.']);if(errors(err))return;const before=(p.receivedQty||0)+'/'+p.qty;commit('Goods received and stock updated.',()=>{p.receivedQty=(p.receivedQty||0)+ +d.qty;p.status=p.receivedQty===p.qty?'Received':'Partially received';org().stock.push({id:'B-'+(1001+org().stock.length),product:p.product,batch:d.batch,expiry:d.expiry,qty:+d.qty,location:'Main site'});logChange(p.id+' goods receipt',before,p.receivedQty+'/'+p.qty);});},'Confirm receipt',`<p>${esc(p.id)} · ${remaining} pack(s) outstanding. Separate batches can be received in later steps.</p>`);}
 function salesV2(){return header('Sales & returns','Mock transactions only; completed invoices retain their original price.',button('View credit notes','credit-notes')+button('Create mock sale','sale-add','',true))+`<section class="card">${org().sales.map(s=>row(s.id+' · '+s.customer,(s.productName||item(s.product).name)+' · '+s.qty+' packs · '+money(s.qty*s.price)+(s.returned?' · '+s.returned+' returned':''),button('View invoice','sale-detail',s.id)+((s.returned||0)<s.qty?button('Return sale','sale-return',s.id):''),s.status)).join('')}</section>`;}
 function returnSaleV2(id){const s=org().sales.find(x=>x.id===id),remaining=s.qty-(s.returned||0);form('Return sale',input('qty','Quantity to return',remaining,'number',`min="1" max="${remaining}" step="1"`)+input('reason','Return reason'),d=>{const err=[];if(!Number.isInteger(+d.qty)||+d.qty<1||+d.qty>remaining)err.push(['qty','Enter 1 to '+remaining+' packs.']);if(!d.reason.trim())err.push(['reason','Enter a return reason.']);if(errors(err))return;close();modal('Confirm sale return',details([['Invoice',s.id],['Customer',s.customer],['Return quantity',d.qty],['Mock credit amount',money(+d.qty*s.price)]])+'<p>Returned products are quarantined, not restored to sellable stock. A credit note is previewed only; no money moves.</p>',[{label:'Keep sale'},{label:'Confirm mock return',primary:true,run:()=>{const before=(s.returned||0)+'/'+s.qty;s.returned=(s.returned||0)+ +d.qty;s.status=s.returned===s.qty?'Returned':'Partially returned';s.returnReason=d.reason;(org().creditNotes??=[]).push({invoice:s.id,qty:+d.qty,amount:+d.qty*s.price,reason:d.reason});logChange(s.id+' returned to quarantine',before,s.returned+'/'+s.qty);render();toast('Mock return recorded. Sellable stock unchanged.');}}]);},'Review return');}
 function inventoryV2(){const quarantined=org().sales.filter(s=>s.returned);return header('Inventory','Stock is tracked by batch and location. Expired batches cannot be sold.')+searchbar('Search product, batch or location')+`<section class="card">${org().stock.filter(s=>(item(s.product).name+' '+s.batch+' '+s.location).toLowerCase().includes(query.toLowerCase())).map(s=>row(item(s.product).name,s.batch+' · '+s.location+' · '+s.qty+' packs · Expires '+date(s.expiry),button('View batch','batch-detail',s.id)+button('Adjust stock','stock-adjust',s.id)+button('Transfer stock','stock-transfer',s.id),s.expiry<today?'Expired':s.qty<10?'Low stock':'Available')).join('')||empty('No batches match.')}</section><section class="card"><h2>Return quarantine</h2>${quarantined.map(s=>`<p>${esc(s.id)} · ${s.returned} pack(s) quarantined · ${esc(s.returnReason||'Reason not recorded')}</p>`).join('')||'<p>No returned stock in quarantine.</p>'}</section>`;}
 function batchDetailV2(id){const s=org().stock.find(x=>x.id===id);modal('Batch details',details([['Product',item(s.product).name],['Batch',s.batch],['Location',s.location],['Quantity',s.qty],['Expiry',date(s.expiry)],['Sale eligibility',s.expiry<today?'Blocked: expired':'Available if product is active']])+'<p>Adjust stock records a mock cycle count with reason. Transfers move only sellable stock between locations.</p>');}
 function stockTransfer(id){const s=org().stock.find(x=>x.id===id),destinations=org().locations.filter(l=>l.name!==s.location);if(s.expiry<today)return modal('Transfer stock','<p>Expired batches cannot be transferred as sellable stock. Review quarantine handling first.</p>');if(!s.qty)return modal('Transfer stock','<p>No stock is available to transfer.</p>');if(!destinations.length)return modal('Transfer stock','<p>Add another location in Organization settings before transferring stock.</p>');form('Transfer stock',select('destination','Destination location',destinations.map(l=>l.name))+input('qty','Quantity to transfer',s.qty,'number',`min="1" max="${s.qty}" step="1"`),d=>{if(errors(!Number.isInteger(+d.qty)||+d.qty<1||+d.qty>s.qty?[['qty','Enter 1 to '+s.qty+' packs.']]:[]))return;const from=s.location,amount=+d.qty;close();modal('Confirm stock transfer',details([['Batch',s.batch],['From',from],['To',d.destination],['Quantity',amount]])+'<p>No external shipment or dispensing occurs.</p>',[{label:'Cancel'},{label:'Confirm transfer',primary:true,run:()=>{if(amount===s.qty)s.location=d.destination;else{s.qty-=amount;org().stock.push({...s,id:'B-T'+(1001+org().stock.length),qty:amount,location:d.destination});}logChange(s.batch+' stock transferred',from,d.destination+' · '+amount+' packs');render();toast('Mock stock transfer recorded.');}}]);},'Review transfer');}
 function reportsPage(){const o=org(),records=orgKey==='pharmacy'?[['Sales recorded',o.sales.length],['Units on hand',o.stock.reduce((n,s)=>n+s.qty,0)],['Expired batches',o.stock.filter(s=>s.expiry<today).length],['Purchase orders',o.purchases.length]]:[['Open bookings',o.bookings.filter(b=>!['Cancelled','Released'].includes(b.status)).length],['Active staff',o.staff.filter(s=>s.status==='Active').length],['Closures',o.closures.length],['Administrative changes',o.activity.length]];return header('Reports','Operational mock summaries for '+o.name,button('Preview report export','report-export','',true))+`<div class="stats">${records.slice(0,3).map(([label,n])=>`<div class="card"><strong>${n}</strong><p>${esc(label)}</p></div>`).join('')}</div><section class="card"><h2>Current mock snapshot</h2>${records.map(([label,n])=>`<p><strong>${esc(label)}</strong> · ${n}</p>`).join('')}<p class="read-note">These figures use browser-saved mock data. No financial reconciliation or production report is generated.</p></section>`;}
 function supportPage(){const o=org();o.supportTickets??=[];o.noticePrefs??={operational:true,stock:true};return header('Notifications & support','Prototype preferences and operational support for '+o.name,button('Create support request','support-add','',true))+`<div class="grid"><section class="card"><h2>Notification preferences</h2><p>These local preferences do not subscribe anyone to messages.</p><label class="check-row"><input type="checkbox" data-pref="operational" ${o.noticePrefs.operational?'checked':''}> Operational alerts</label><label class="check-row"><input type="checkbox" data-pref="stock" ${o.noticePrefs.stock?'checked':''}> Stock and capacity alerts</label><h3>Mock delivery history</h3><p>No external messages have been sent in this prototype.</p></section><section class="card"><h2>Support requests</h2>${o.supportTickets.map(t=>row(t.subject,t.category+' · '+t.status,button('View support request','support-detail',t.id))).join('')||'<p>No mock support requests yet.</p>'}<p>For urgent clinical or safety incidents, use your established organization process.</p></section></div>`;}
 function supportAdd(){form('Create support request',select('category','Issue category',['Access','Scheduling','Pharmacy operations','Diagnostic operations','Other'])+input('subject','Short subject')+`<div class="form-group"><label class="form-label" for="description">What needs help?</label><textarea class="form-control" id="description" name="description"></textarea><span class="field-error" id="description-error"></span></div>`,d=>{const err=[];if(!d.subject.trim())err.push(['subject','Enter a short subject.']);if(!d.description.trim())err.push(['description','Describe the issue.']);if(errors(err))return;commit('Mock support request saved. Nothing was sent.',()=>org().supportTickets.push({...d,id:'SUPPORT-'+(org().supportTickets.length+1),status:'Draft · not sent'}));},'Save mock request','<p>This creates a local draft only. Do not enter patient or other sensitive information.</p>');}
 function staffPageV2(){const rows=search(org().staff,['name','role','assignment']).sort((a,b)=>staffSort==='Name Z–A'?b.name.localeCompare(a.name):staffSort==='Role'?a.role.localeCompare(b.role)||a.name.localeCompare(b.name):a.name.localeCompare(b.name)),size=5,pagesCount=Math.max(1,Math.ceil(rows.length/size));staffPageNum=Math.min(staffPageNum,pagesCount);return header('Staff & access','Staff belonging to '+org().name,button('Add staff','staff-add','',true))+searchbar('Search staff or role',['Active','Inactive'])+`<div class="search-bar">${select('staff-sort','Sort staff',['Name A–Z','Name Z–A','Role'],staffSort)}${button('Prepare selected invitations','staff-bulk')}</div><section class="card">${rows.slice((staffPageNum-1)*size,staffPageNum*size).map(s=>`<div class="staff-select-row"><label class="check-row"><input type="checkbox" data-staff-select="${esc(s.id)}" ${selectedStaff.has(s.id)?'checked':''} ${s.self?'disabled':''}><span class="sr-only">Select ${esc(s.name)}</span></label>${row(s.name,s.role+' · '+s.assignment,button('View staff','staff-detail',s.id)+button('Edit staff','staff-edit',s.id),s.status)}</div>`).join('')||empty('Try a different name or role.')}</section><div class="pagination"><span>Page ${staffPageNum} of ${pagesCount} · ${rows.length} staff</span>${staffPageNum>1?button('Previous page','staff-page','previous'):'<button class="btn btn-ghost" disabled>Previous page</button>'}${staffPageNum<pagesCount?button('Next page','staff-page','next'):'<button class="btn btn-ghost" disabled>Next page</button>'}</div>`;}
 function bulkInvitations(){const staff=org().staff.filter(s=>selectedStaff.has(s.id)&&!s.self);if(!staff.length)return modal('Prepare selected invitations','<p>Select one or more staff members first.</p>');modal('Prepare selected invitations',`<p>${staff.map(s=>esc(s.name)).join(', ')}</p><p>Local preview only. No messages or real accounts are created.</p>`,[{label:'Cancel'},{label:'Mark invitations prepared',primary:true,run:()=>{staff.forEach(s=>{const before=s.account||'Not invited · prototype';s.account='Invitation prepared · prototype';logChange('Invitation prepared for '+s.name,before,s.account);});selectedStaff.clear();render();toast('Mock invitations prepared; no messages sent.');}}]);}
 function settingsV2(){return settings()+(orgKey==='hospital'?'':`<section class="card"><div class="page-header"><div><h2>Locations</h2><p>Mock operational locations and display hours. Resource schedules are managed separately.</p></div>${button('Add location','location-add')}</div>${org().locations.map(l=>row(l.name,l.address+' · '+l.hours,button('Edit location','location-edit',l.id))).join('')}</section>`);}
 function locationEdit(id){const l=org().locations.find(x=>x.id===id);form(l?'Edit location':'Add location',input('name','Location name',l?.name)+input('address','Location address',l?.address)+input('hours','Display opening hours',l?.hours||org().hours),d=>{const err=[];if(!d.name.trim())err.push(['name','Enter a location name.']);if(!d.address.trim())err.push(['address','Enter a location address.']);if(!d.hours.trim())err.push(['hours','Enter display opening hours.']);if(org().locations.some(x=>x.id!==id&&x.name.toLowerCase()===d.name.trim().toLowerCase()))err.push(['name','This location already exists.']);if(errors(err))return;const before=l?.name||'New location';commit(l?'Location updated.':'Mock location added.',()=>{if(l){const previous=l.name;Object.assign(l,d);org().resources.forEach(r=>{if(r.location===previous)r.location=l.name;});org().stock?.forEach(s=>{if(s.location===previous)s.location=l.name;});}else org().locations.push({...d,id:'LOC-'+(org().locations.length+1)});logChange('Location profile saved',before,d.name);});},'Save location','<p>Location display hours do not change resource availability or existing bookings.</p>');}
 function helpV2(){return help()+`<section class="card"><h2>Interface state previews</h2><p>Review recoverable mock states before connecting real services.</p><div class="actions">${button('Preview loading state','state-preview','loading')}${button('Preview service error','state-preview','error')}${button('Preview access denied','state-preview','denied')}</div></section>`;}
 function statePreview(kind){if(kind==='loading')return modal('Loading preview','<p role="status">Loading organization data…</p><p>No network request is made.</p>',[{label:'Close preview'},{label:'Simulate completion',primary:true,run:()=>modal('Data available','<p>Mock organization data is available again.</p>')}]);if(kind==='denied')return modal('Access denied','<p>Your assigned organization role does not allow this operation. No data was changed.</p>',[{label:'Close preview'},{label:'Return to dashboard',primary:true,run:()=>go('dashboard')}]);modal('Service unavailable','<p>The mock service could not load this view. Existing work is preserved.</p>',[{label:'Close preview'},{label:'Retry mock request',primary:true,run:()=>modal('Retry successful','<p>Mock data is available again. No external request was made.</p>')}]);}
 const pages={dashboard:dashboardV2,staff:staffPageV2,catalogue,schedule:scheduleV2,appointments:bookingsV2,orders:bookingsV2,departments:departmentsV2,inpatient:()=>overviewV2('inpatient'),emergency:()=>overviewV2('emergency'),inventory:inventoryV2,suppliers,purchases:purchasesV2,sales:salesV2,settings:settingsV2,activity:activityV2,reports:reportsPage,support:supportPage,help:helpV2};
 function render(){root.innerHTML=pages[page]();if(orgKey==='hospital'&&page==='appointments'){root.insertAdjacentHTML('beforeend',WalkinUI.slot());WalkinUI.mount({role:'admin',render});}document.querySelector('#page-title').textContent=root.querySelector('h1').textContent;document.querySelector('#org-name').textContent=org().name;document.querySelector('#org-type').textContent=org().type;document.querySelectorAll('[data-screen]').forEach(b=>{b.hidden=!!b.dataset.types&&!b.dataset.types.split(' ').includes(orgKey);b.classList.toggle('active',b.dataset.screen===page);if(b.dataset.screen===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});root.querySelector('#search')?.addEventListener('input',e=>{query=e.target.value;const start=e.target.selectionStart;render();const input=root.querySelector('#search');input.focus();input.setSelectionRange(start,start);});root.querySelector('#filter')?.addEventListener('change',e=>{filter=e.target.value;render();root.querySelector('#filter')?.focus();});}
