 root.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;if(pages[action])return go(action);const map={'appointment-create':createAppointment,'clear':()=>{query='';filter='All';render();},'staff-add':()=>staffEdit(),'staff-edit':()=>staffEdit(id),'staff-detail':()=>staffDetailV2(id),'catalogue-add':()=>catalogueEdit(),'catalogue-edit':()=>catalogueEdit(id),'availability-check':checkAvailability,'closure-add':closureAdd,'closure-detail':()=>closureDetail(id),'booking-detail':()=>bookingDetail(id),'settings-edit':settingsEdit,'heading-preview':()=>modal('Document heading preview',`<h2>${esc(org().invoice)}</h2><p>${esc(org().address)}</p><p>${esc(org().phone)}</p><p>Sample document heading. Existing issued documents are unchanged.</p>`),'stock-adjust':()=>stockAdjust(id),'supplier-add':()=>supplierEdit(),'supplier-edit':()=>supplierEdit(id),'purchase-add':purchaseAdd,'purchase-receive':()=>purchaseReceive(id),'sale-add':saleAdd,'sale-return':()=>returnSale(id),'batch-detail':()=>{const s=org().stock.find(x=>x.id===id);modal('Batch details',details([['Product',item(s.product).name],['Batch',s.batch],['Quantity',s.qty],['Expiry',date(s.expiry)],['Sale eligibility',s.expiry<today?'Blocked: expired':'Available if product is active']]));},'purchase-detail':()=>{const p=org().purchases.find(x=>x.id===id);modal('Purchase details',details([['Order',p.id],['Supplier',p.supplier],['Product',(p.productName||item(p.product).name)],['Quantity',p.qty],['Unit cost',money(p.cost)],['Status',p.status]]));},'sale-detail':()=>{const s=org().sales.find(x=>x.id===id);modal('Invoice preview',details([['Invoice',s.id],['Customer',s.customer],['Date',date(s.date)],['Product',s.productName||item(s.product).name],['Quantity',s.qty],['Original unit price',money(s.price)],['Total',money(s.qty*s.price)],['Status',s.status]])+(s.returned?'<p>Returned quantity: '+s.returned+' · Quarantined. '+esc(s.returnReason)+'</p>':''));},'department-add':()=>form('Add department',input('name','Department name'),d=>{const err=[];if(!d.name.trim())err.push(['name','Enter a department name.']);if(org().departments.some(x=>x.name.toLowerCase()===d.name.trim().toLowerCase()))err.push(['name','This department already exists.']);if(errors(err))return;commit('Department added.',()=>org().departments.push({id:'D'+(org().departments.length+1),name:d.name.trim()}));},'Save department'),'department-detail':()=>{const d=org().departments.find(x=>x.id===id);modal('Department assignments',`<h2>${esc(d.name)}</h2><p>${org().staff.filter(s=>s.assignment===d.name).map(s=>esc(s.name+' · '+s.role+' · '+s.status)).join('<br>')||'No staff assigned.'}</p><p>Update assignments from Staff & access.</p>`,[{label:'Close details'},{label:'Open staff','run':()=>go('staff')}]);},'bed-detail':()=>modal('Occupancy details',details([['Ward / bed','Ward A / A-01'],['Patient','Ravi Kumar · PAT-1042'],['Admitted','12 Sep 2026'],['Status','Occupied'],['Available beds','A-02, A-03']])+'<p>Admission, transfer and discharge decisions remain with the authorized care team. This screen is read-only.</p>'),'emergency-detail':()=>modal('Emergency request',details([['Request','ER-1001'],['Location','Clinic entrance'],['Status','Acknowledged'],['Assigned team','Duty team']])+'<p>This is a sample coordination record. No ambulance request is sent and no clinical prioritization is performed.</p>')};map[action]?.();});
 root.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;if(['booking-detail','closure-detail','staff-add','staff-edit','resource-edit','resource-add','availability-check','hours-exception-add','closure-add','department-detail','purchase-receive','purchase-discrepancy','sale-return','stock-transfer','batch-detail','credit-notes'].includes(action)){ev.stopImmediatePropagation();if(action==='booking-detail')bookingDetailV2(id);else if(action==='closure-detail')closureDetailV2(id);else if(action==='resource-edit')resourceEdit(id);else if(action==='resource-add')resourceAdd();else if(action==='availability-check')checkAvailabilityV2();else if(action==='hours-exception-add')hoursExceptionAdd();else if(action==='closure-add')closureAddV2();else if(action==='department-detail')departmentDetailV2(id);else if(action==='purchase-receive')purchaseReceiveV2(id);else if(action==='purchase-discrepancy')purchaseDiscrepancy(id);else if(action==='sale-return')returnSaleV2(id);else if(action==='stock-transfer')stockTransfer(id);else if(action==='batch-detail')batchDetailV2(id);else if(action==='credit-notes')modal('Mock credit notes',`<p>No payment or refund is processed.</p>${(org().creditNotes||[]).map(c=>`<p>${esc(c.invoice)} · ${c.qty} pack(s) · ${money(c.amount)} · ${esc(c.reason)}</p>`).join('')||'<p>No credit notes yet.</p>'}`);else staffEditV2(action==='staff-add'?undefined:id);}},true);
